<?php
namespace App\Console\Commands;
use App\Models\Activity;use App\Services\ArmoryNotificationService;use Illuminate\Console\Command;
final class NotifyUpcomingActivities extends Command {protected $signature='activities:notify-upcoming';protected $description='Notify members about activities starting within 30 minutes';public function handle(ArmoryNotificationService $notifications):int{$activities=Activity::query()->whereNull('completed_at')->whereBetween('occurred_at',[now(),now()->addMinutes(30)])->with('definition:id,name')->get();$members=$notifications->activeMembers();foreach($activities as $activity)$notifications->notify($members,'activity_upcoming','Событие скоро начнётся',$activity->definition->name.' начнётся '.$activity->occurred_at->format('d.m.Y H:i').'.','/activities/'.$activity->id,'activity-upcoming-'.$activity->id);return self::SUCCESS;}}
